using System;using System.IO;using OsuLegacy;
public static class BeatmapEditorTests {
 static int count;static void Check(bool b,string s){count++;if(!b)throw new Exception(s);}static bool Near(double a,double b){return Math.Abs(a-b)<.01;}
 public static int Main(){string root=Path.Combine(Path.GetTempPath(),"osu-editor-"+Guid.NewGuid());Directory.CreateDirectory(root);try{
  string path=Path.Combine(root,"map.osu");File.WriteAllBytes(Path.Combine(root,"audio.wav"),new byte[44]);
  string original="osu file format v14\r\n[General]\r\nAudioFilename: audio.wav\r\nMode: 0\r\n[Metadata]\r\nTitle:Original title\r\nArtist:音楽\r\nVersion:Hard\r\nBeatmapID:1234\r\nBeatmapSetID:567\r\n[Difficulty]\r\nCircleSize:4\r\nOverallDifficulty:5\r\nSliderMultiplier:1.4\r\n[Events]\r\n2,4000,5000\r\n// keep storyboard data\r\nSprite,Foreground,Centre,\"sprite.png\",320,240\r\n[TimingPoints]\r\n100,500,3,2,7,65,1,8\r\n1100,-50,3,2,7,65,0,9\r\n2000,400,4,1,0,100,1,0\r\n[Colours]\r\nCombo1 : 255,0,128\r\n[HitObjects]\r\n80,80,1100,5,2,2:3:4:85:custom.wav\r\n160,160,1600,2,4,B|200:160|240:200,2,120,2|4|8,1:2|2:3|3:1,0:0:0:0:\r\n256,192,2600,8,0,3600,0:0:0:0:\r\n[UnknownSection]\r\nFutureProperty:keep me\r\n";
  File.WriteAllText(path,original);var doc=BeatmapEditorDocument.Load(path);Check(!doc.Dirty && doc.Objects.Count==3,"loads clean document");Check(doc.Mode==0 && doc.Get("Metadata","Artist","")=="音楽","mode and unicode metadata");Check(Near(doc.Snap(50,4),100),"snap before first timing point uses its origin");Check(Near(doc.Snap(1170,4),1225),"beat snapping uses active timing origin");Check(Near(doc.Snap(1990,1),2000),"snap clamps to next timing point");Check(Near(doc.TimingAt(1600).Velocity,2),"inherited velocity");Check(Near(doc.EndTime(doc.Objects[1]),2028.5714286),"slider duration respects repeats and SV");
  doc.SelectedId=doc.Objects[1].Id;doc.Before();doc.Selected.Move(176,176);doc.Changed();Check(doc.Dirty && doc.Selected.Fields[5]=="B|216:176|256:216","moving a curve translates all control points");Check(doc.Selected.Fields[8]=="2|4|8" && doc.Selected.Fields[9]=="1:2|2:3|3:1","edge samples untouched");doc.Undo();Check(!doc.Dirty && doc.Objects[1].X==160,"undo restores original clean state");doc.Redo();Check(doc.Dirty && doc.Objects[1].X==176,"redo restores movement");
  foreach(ObjectKind kind in new ObjectKind[]{ObjectKind.Circle,ObjectKind.Slider,ObjectKind.Spinner,ObjectKind.Hold}){var obj=doc.Add(kind,4200,64,64,192,64,4);Check(obj.Kind==kind && obj.Time>=0,"add "+kind);if(kind==ObjectKind.Slider)Check(Near(obj.PreviewPath.Position(1).X,192),"new slider reaches dragged endpoint");}
  doc.SelectedId=doc.Objects[0].Id;doc.Duplicate(7000);Check(doc.Selected.Time==7000 && doc.Selected.Fields[5]=="2:3:4:85:custom.wav","duplicate preserves custom sample");doc.Delete();Check(doc.Selected==null,"delete clears selection");doc.Undo();Check(doc.Objects.Exists(delegate(EditorObject o){return o.Time==7000;}),"undo deletion");
  doc.ChangeKey("Metadata","Title","Edited title");doc.Timing(1100,150,1.5,false);Check(Near(doc.TimingAt(1200).BeatLength,400) && Near(doc.TimingAt(1200).Velocity,1.5),"timing replacement");Check(doc.Serialize().Contains("1100,400,3,2,7,65,1,8"),"timing edit preserves meter, banks, custom index, volume and other effects");
  string saved=doc.Save();Check(saved!=path && File.Exists(saved) && !doc.Dirty,"save edited copy");Check(File.ReadAllText(path)==original,"original remains byte-for-byte untouched");var reopened=BeatmapEditorDocument.Load(saved);Check(reopened.Title=="Edited title" && reopened.Objects.Count==doc.Objects.Count,"saved copy reopens");Check(reopened.SavePath==saved,"reopened editor copy saves back to its own path");Check(reopened.Get("Metadata","BeatmapID","")=="0" && reopened.Get("Metadata","BeatmapSetID","")=="567","detach difficulty ID and retain set grouping");string text=File.ReadAllText(saved);Check(text.Contains("FutureProperty:keep me") && text.Contains("Sprite,Foreground") && text.Contains("Combo1 : 255,0,128") && text.Contains("\r\n"),"unknown fields, storyboard, colours and line endings preserved");
  doc.ChangeKey("Metadata","Creator","Mapper");doc.Save();Check(File.Exists(saved+".bak") && Beatmap.Load(saved).Creator=="Mapper","update uses backup and parses in gameplay loader");File.AppendAllText(saved,"// external change\n");bool refused=false;try{doc.Save();}catch(IOException){refused=true;}Check(refused && File.ReadAllText(saved).EndsWith("// external change\n"),"external edit conflict refuses overwrite");
  var moved=BeatmapEditorDocument.Load(path);moved.MoveTiming(100,150);Check(Near(moved.TimingAt(500).Time,150) && moved.Serialize().Contains("150,500,3,2,7,65,1,8"),"offset moves preserve timing sample settings");moved.Undo();Check(Near(moved.TimingAt(500).Time,100),"offset undo");var empty=BeatmapEditorDocument.Load(path);empty.Before();empty.Objects.Clear();empty.Changed();var emptyPath=empty.Save();Check(BeatmapEditorDocument.Load(emptyPath).Objects.Count==0,"empty difficulty saves and reopens for composition");
  var maniaText=original.Replace("Mode: 0","Mode: 3");int from=maniaText.IndexOf("[HitObjects]"),to=maniaText.IndexOf("[UnknownSection]");maniaText=maniaText.Substring(0,from)+"[HitObjects]\r\n64,192,1000,128,0,2000:0:0:0:0:\r\n"+maniaText.Substring(to);string mp=Path.Combine(root,"mania.osu");File.WriteAllText(mp,maniaText);var mania=BeatmapEditorDocument.Load(mp);mania.SelectedId=mania.Objects[0].Id;mania.Duplicate(3000);Check(mania.Selected.End==4000,"duplicate hold preserves duration");Check(Beatmap.Load(mania.Save()).Mode==3,"mania saved difficulty is playable");
  var ui=new LazerUi();ui.BeginBeatmapEditor();ui.SetBeatmapEditor(BeatmapEditorDocument.Load(path),10000);var surface=new SvgUiSurface("port/Assets");ui.Draw(surface,0);surface.Save("build/ui-preview/beatmap-editor.svg");Check(ui.Screen==UiScreen.BeatmapEditor && !ui.EditorPlaying,"editor screen opens stopped");ui.MenuPointer(0,30,86);ui.MenuPointer(0,120,100);ui.MenuPointer(2,120,100);Check(ui.EditorDocument.Objects.Count==4,"circle touch placement");ui.Draw(new SvgUiSurface("port/Assets"),.1);ui.MenuPointer(0,30,119);ui.MenuPointer(0,180,120);ui.MenuPointer(1,250,150);ui.MenuPointer(2,250,150);Check(ui.EditorDocument.Selected.Kind==ObjectKind.Slider && ui.EditorDocument.Selected.Length>100,"slider touch drag placement");ui.Draw(new SvgUiSurface("port/Assets"),.2);ui.MenuPointer(0,10,10);Check(ui.Screen==UiScreen.BeatmapEditor,"dirty exit requires save/discard choice");ui.Draw(new SvgUiSurface("port/Assets"),.3);ui.MenuPointer(0,360,180);Check(ui.Screen==UiScreen.BeatmapEditor,"cancel exit retains draft");
  var picker=new LazerUi();picker.OpenEditorPicker();Check(picker.EditorPicking,"editor picker opens in edit mode");picker.OpenSongs();Check(!picker.EditorPicking,"regular solo entry clears edit-picker mode");Console.WriteLine("PASS: "+count+" beatmap editor placement, timing, curves, undo/redo, metadata, preservation, safe saves, conflicts, mania and touch navigation checks");return 0;
 }finally{Directory.Delete(root,true);}}
}
